/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to a PDF file. &IsAuthorized = SecGAMIsAuthByFunctionalityKey.Udp(!'trnsdoencasww_Execute') If &IsAuthorized
LoadWWPContext.Call(&WWPContext)
Do 'LoadGridState'
&Title = "Lista de Cadastro de Doenças"
//Report Template Source Header &AppName = "DVelop Software Solutions" &Phone = !"+1 550 8923" &Mail = !"info@mail.com" &Website = !"http://www.web.com" &AddressLine1 = !"French Boulevard 2859" &AddressLine2 = !"Downtown" &AddressLine3 = !"Paris, France" Print printTitle End Footer &PageInfo = "Page: " + &Page.ToString().Trim() &DateInfo = "Date: " + &Today.ToFormattedString() Print printFooter End
Do 'PrintFilters'
Do 'PrintColumnTitles'
Do 'PrintData'
Do 'PrintFooter'
EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If not (&TFdoenCodigo.IsEmpty() AND &TFdoenCodigo_To.IsEmpty()) print printBlockTFdoenCodigo &TFdoenCodigo_To_Description = format('%1 (%2)', "Código", "WWP_TSTo") print printBlockTFdoenCodigo_To EndIf If not &TFdoenDescricao_Sel.IsEmpty() print printBlockTFdoenDescricao_Sel Else If not &TFdoenDescricao.IsEmpty() print printBlockTFdoenDescricao EndIf EndIf &TFdoenStatus_Sels.FromJson(&TFdoenStatus_SelsJson) If not &TFdoenStatus_Sels.Count = 0 &i = 1 For &TFdoenStatus_Sel in &TFdoenStatus_Sels If &i = 1 &TFdoenStatus_SelDscs = '' Else &TFdoenStatus_SelDscs += ', ' EndIf &FilterTFdoenStatus_SelValueDescription = '' Do Case Case &TFdoenStatus_Sel.ToString().Trim() = !"S" &FilterTFdoenStatus_SelValueDescription = "Sim"
Case &TFdoenStatus_Sel.ToString().Trim() = !"N" &FilterTFdoenStatus_SelValueDescription = "Não"
EndCase
&TFdoenStatus_SelDscs += &FilterTFdoenStatus_SelValueDescription &i += 1 EndFor print printBlockTFdoenStatus_Sel EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsdoencas order doenDescricao when &OrderedBy = 1 AND &OrderedDsc = False order (doenDescricao) when &OrderedBy = 1 AND &OrderedDsc = True order doenCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (doenCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order doenStatus when &OrderedBy = 3 AND &OrderedDsc = False order (doenStatus) when &OrderedBy = 3 AND &OrderedDsc = True
using trnsdoencasWWDS(&TFdoenCodigo, &TFdoenCodigo_To, &TFdoenDescricao, &TFdoenDescricao_Sel, &TFdoenStatus_Sels) Where prefCodigo = &prefCodigo &doenStatusDescription = '' Do Case Case doenStatus.ToString().Trim() = !"S" &doenStatusDescription = "Sim"
Case doenStatus.ToString().Trim() = !"N" &doenStatusDescription = "Não"
EndCase
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsdoencasWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsdoencasWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsdoencasWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFDOENCODIGO" &TFdoenCodigo.FromString(&GridStateFilterValue.Value) &TFdoenCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDOENDESCRICAO" &TFdoenDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDOENDESCRICAO_SEL" &TFdoenDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDOENSTATUS_SEL" &TFdoenStatus_SelsJson = &GridStateFilterValue.Value &TFdoenStatus_Sels.FromJson(&TFdoenStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforePrintLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'AfterPrintLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintFooter'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */

Output_file("trnsdoencasWWExportReport","PDF");

